// Builds worker/worker.js, the one file you paste into a Cloudflare Worker.
// It bundles data/cert-types.json + tools/detect-core.js + tools/worker-handler.js. Re-run after changing any of them
// (double-click "Build Cloudflare Worker.bat"). Never edit worker/worker.js by hand.
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const read = (...p) => fs.readFileSync(path.join(root, ...p), 'utf8');
const catalog = JSON.parse(read('data', 'cert-types.json'));
const out = [
  '// GENERATED by tools/build-worker.js. Edit tools/detect-core.js, tools/worker-handler.js or data/cert-types.json, then rebuild.',
  '// COBO Snap Your Wall: the Cloudflare Worker that holds the Gemini key and reads wall photos.',
  `const CATALOG = ${JSON.stringify(catalog)};`,
  '',
  read('tools', 'detect-core.js').replace(/^if \(typeof module.*$/m, '').trim(),
  '',
  read('tools', 'worker-handler.js').trim(),
  '',
].join('\n');
fs.mkdirSync(path.join(root, 'worker'), { recursive: true });
fs.writeFileSync(path.join(root, 'worker', 'worker.js'), out);
console.log(`worker/worker.js written (${Math.round(out.length / 1024)} KB, ${catalog.types.length} certificate types)`);
